                    <div class="mt-1">
                        Quantity: 
                        <button class="btn btn-sm btn-secondary" onclick="changeQty(${index}, -1)">-</button>
                        <span class="mx-2">${item.quantity}</span>
                        <button class="btn btn-sm btn-secondary" onclick="changeQty(${index}, 1)">+</button>
                        | Subtotal: RM${subtotal.toFixed(2)}
                    </div>`;
                    container.appendChild(div);
                });

                document.getElementById('subtotal').value = `RM ${total.toFixed(2)}`;
            }

            function changeQty(index, amount) {
                selectedItems[index].quantity += amount;
                if (selectedItems[index].quantity <= 0) selectedItems.splice(index, 1);
                updateSelectedItems();
            }

            function removeItem(index) {
                selectedItems.splice(index, 1);
                updateSelectedItems();
            }

            function submitOrder(e) {
                e.preventDefault();

                if (selectedItems.length === 0) {
                    alert("Please select at least one item.");
                    return;
                }

                const name = document.getElementById('custName').value;
                const phone = document.getElementById('custPhone').value;

                fetch('../api/place_order.php', {
                    method: 'POST',
                    headers: {
                    'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({
                    name,
                    phone,
                    items: selectedItems
                    })
                })
                .then(res => res.json())
                .then(data => {
                    console.log(data);
                    if (data.success) {
                    $('#orderModal').modal('hide');
                    document.getElementById('statusModalBody').innerText = "Order placed successfully!";
                    $('#statusModal').modal('show');
                    selectedItems = [];
                    updateSelectedItems();
                    } else {
                    document.getElementById('statusModalBody').innerText = "Error: " + data.message;
                    $('#statusModal').modal('show');
                    }
                })
                .catch(error => {
                console.error("Fetch error:", error);
                document.getElementById('statusModalBody').innerText = "Failed to send request. Please try again.";
                $('#statusModal').modal('show');
                });

                $('#statusModal').on('hidden.bs.modal', function () {
                $('body').removeClass('modal-open'); // remove modal-open class
                $('.modal-backdrop').remove();       // remove leftover backdrop
            });
            }
        </script>

